# Você deve montar a chave usando o template do script original:
# "picoCTF{1n_7h3_kk3y_of_" + [caracteres do hash] + "}"

# Extraia o hash de BENNETT
h = hashlib.sha256(b"BENNETT").hexdigest()

# A ordem dos caracteres segundo o check_key é: 4, 5, 3, 6, 2, 7, 1, 8
chave_dinamica = h[4] + h[5] + h[3] + h[6] + h[2] + h[7] + h[1] + h[8]

# Monte a chave completa
key_str = "picoCTF{1n_7h3_kk3y_of_" + chave_dinamica + "}"

# O Fernet precisa da chave em base64
key_base64 = base64.b64encode(key_str.encode())
f = Fernet(key_base64)

# Descriptografa
try:
    decrypted = f.decrypt(full_version_blob)
    print(decrypted.decode())
except Exception as e:
    print(f"Erro: {e}")